def bind_assessment_to_work_item(assessment: dict, item: dict) -> dict:
    assessment["direction_ref"] = {
        "work_item_id": item["work_item_id"],
        "direction_version": item["data"]["direction_confirmation"][
            "direction_version"
        ],
    }
